let phase=0,heard=new Set(),rescued=0,dialogueTarget=null,gameStarted=false,dead=false,zoom=72;const keys={};const toastEl=document.querySelector('#toast');let toastTimer;function toast(t){toastEl.textContent=t;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2800)}
function quest(title,text,progress){document.querySelector('#questTitle').textContent=title;document.querySelector('#questText').textContent=text;document.querySelectorAll('.pip').forEach((p,i)=>p.classList.toggle('done',i<progress))}
const dialogueEl=document.querySelector('#dialogue');function openDialogue(npc){dialogueTarget=npc;document.querySelector('#speaker').textContent=npc.userData.name+(npc.userData.job==='elder'?' · Elder':npc.userData.job==='shepherd'?' · Shepherd':'');dialogueEl.classList.add('show');document.querySelector('#say').focus();let line=npc.userData.job==='elder'?"You’ve come along the Lanternroad, stranger. I am Mara. We’ve had little cause to welcome travelers lately—but you look like you know how to listen.":npc.userData.job==='shepherd'?"The ridge flocks are restless. Smoke on the south road, and no birds near the old watchpost. Bad signs, all of them.":"Warm bread, cold news. The raiders came by night. Took three from our village and left their own marks on the road.";if(phase>=1)line=npc.userData.job==='elder'?"The old watchpost, south beyond the standing stones. That’s where they’ve taken Seli, Orin and Dara. Please—bring them back.":"The camp is beyond the old stones, down the south track. Five guards, at least. Be careful, friend.":line;document.querySelector('#dialogueText').textContent=line;
if(!npc.userData.captive&&phase===0&&!heard.has(npc.userData.name)){heard.add(npc.userData.name);if(heard.size>=2){phase=1;quest('The Quiet Watchpost','Find the old outpost south of the standing stones. Defeat the guards and free the captives.',1);toast('Quest updated · The Quiet Watchpost')}}}
function closeDialogue(){dialogueEl.classList.remove('show');dialogueTarget=null}document.querySelector('#close').onclick=closeDialogue;
// Public OpenCode Zen completion. It is optional; when offline, concise authored dialogue keeps the game fully playable.
let model=localStorage.getItem('hearthwild-model')||'mimo-v2.6-flash-free';document.querySelector('#modelSet').onclick=()=>{let m=prompt('OpenCode Zen chat model',model);if(m){model=m.trim();localStorage.setItem('hearthwild-model',model)}};
async function npcReply(text){let n=dialogueTarget;if(!n)return;let out=document.querySelector('#dialogueText');out.textContent='Listening…';let zone=player.pos.z<-34?'at the raiders’ watchpost':player.pos.z<14?'in Brackenridge village':'on the Lanternroad';let sys=`You are ${n.userData.name}, an anthropomorphic goat person in a gentle, grounded fantasy RPG called Hearthwild. You are currently ${zone}; the time is a clear morning. The human traveler is a stranger and the player. Raiders from a different species kidnapped three neighbors, Seli, Orin and Dara, who are held at the old watchpost south of the village. Speak naturally in 1-3 sentences, stay in character, and never claim the player did something they have not. If asked to perform an ordinary harmless physical action, cheerfully agree and describe it briefly. Do not promise actions beyond sitting, waving, bowing, stretching, lifting a leg, or resting feet on a nearby surface. Raiders are hostile; do not help them.`;try{let r=await fetch('https://opencode.ai/zen/v1/chat/completions',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer public','X-Opencode-Client':'cli','X-Opencode-Project':'global'},body:JSON.stringify({model,messages:[{role:'system',content:sys},{role:'user',content:text}],stream:false})});if(!r.ok)throw Error('offline');let j=await r.json();out.textContent=j.choices?.[0]?.message?.content||fallbackReply(text,n)}catch{out.textContent=fallbackReply(text,n)}}
function fallbackReply(text,n){let q=text.toLowerCase();if(/sit|chair|rest|feet|kick/.test(q)){n.userData.pose=q.includes('sit')?'sit':'rest';return `${n.userData.name} gives a small nod and settles into a comfortable pose. “There. Better?”`;}if(/wave|hello|hi\b/.test(q)){n.userData.pose='wave';return `${n.userData.name} raises a hand in greeting. “And a good day to you, traveler.”`;}if(/leg|stretch|bow/.test(q)){n.userData.pose='stretch';return `${n.userData.name} obliges with a careful stretch. “Like that?”`;}if(/raid|kidnap|where|outpost|watchpost|captive/.test(q))return n.userData.job==='elder'?"The watchpost lies south, past the old standing stones. I saw them take our neighbors there. Please, bring them home.":"South along the old track, beyond the stones. Their watchpost is hard to miss—and harder to approach.";if(/thank/.test(q))return '“Save your thanks for when everyone is safely home.”';return '“It has been a strange morning. There’s more to this place than the trouble on the south road—but that trouble must come first.”'}
async function say(){if(!dialogueTarget)return;let input=document.querySelector('#say'),text=input.value.trim();if(!text)return;input.value='';await npcReply(text)}document.querySelector('#send').onclick=say;document.querySelector('#say').addEventListener('keydown',e=>{if(e.key==='Enter')say()});
function interact(){if(dialogueTarget){closeDialogue();return}let nearest=null,dist=4;for(const n of [...villagers,...(captives.filter(c=>c.visible))]){let d=player.pos.distanceTo(n.position);if(d<dist){dist=d;nearest=n}}if(nearest){openDialogue(nearest);if(nearest.userData.captive){nearest.userData.rescued=true;nearest.userData.captive=false;rescued++;nearest.userData.job='villager';toast(`${nearest.userData.name} is free · ${rescued}/3`);if(rescued===3){phase=3;quest('The Road Home','Return to Brackenridge. The rescued villagers will follow the lantern road.',3)}}}else toast('There is no one close enough to speak with.')}
function attack(){if(!gameStarted||dialogueTarget||dead)return;player.attack=.42;swordBob=.42;let dir=new THREE.Vector3(-Math.sin(player.yaw),0,-Math.cos(player.yaw));let target=null,best=3.15;for(const e of enemies){if(!e.alive)continue;let delta=e.group.position.clone().sub(player.pos);let d=delta.length();delta.normalize();if(d<best&&dir.dot(delta)>.38){target=e;best=d}}if(target){target.hp--;target.group.rotation.y+=.22;if(target.hp<=0){target.alive=false;scene.remove(target.group);toast('Raider defeated');if(enemies.every(e=>!e.alive)){phase=2;captives.forEach(c=>c.visible=true);quest('A Door Unbarred','The outpost is quiet. Speak to the captives and escort them home.',2);toast('The watchpost is clear · Captives freed')}}else toast(`A clean strike · ${target.hp} more hit${target.hp===1?'':'s'}`)}else if(enemies.some(e=>e.alive&&e.group.position.distanceTo(player.pos)<7))toast('Close the distance and face your foe.');}

